//! 🧪️ One native comparison harness retains the same finite Work authority and typed replies.
use super::*;
use semio_framework_value_control_contract::{OriginalEffectProducer,OriginalEffectAuthority,OriginalEffectAction,OriginalSourceTurnIdentity,RetainedWorkPoll,RetainedWorkOutcome,OriginalEffectReply,OriginalEffectReplyComplete};
use semio_framework_value_retirement::OriginalRetirementFailure;
use semio_framework_value_testing_effect_bank::EffectBank;
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
type Reply<'r>=OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>;
type Complete<'r>=OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>;
pub(crate) fn grant(d:crate::RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
pub(crate) fn paid<'a,'b,P>(bank:&mut EffectBank,authority:&mut OriginalEffectAuthority<P>,context:&mut P::Context<'a,'b>,g:RetainedCloneGrant,units:u64)->RetainedCloneStep where 'b:'a,P:OriginalEffectProducer<Output=RetainedCloneStep,Failure=OriginalRetirementFailure>{
 let mut action:Option<OriginalEffectAction<RetainedCloneStep,OriginalRetirementFailure>>=None;let mut heap=(0usize,0usize);let mut ready=false;
 for _ in 0..128{let((poll,marker),actual)=observe(||bank.run(g,units,|effect|{let before=effect.performed_boundary();let complete=authority.drive(context,effect,&mut action).unwrap();let work=effect.performed_since(before).unwrap();if complete{RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work})}else{RetainedWorkPoll::Pending{work}}}));heap.0+=actual.0;heap.1+=actual.1;if let Some(marker)=marker{assert_eq!(marker,heap.0)}if let RetainedWorkPoll::Complete(turn)=poll{turn.result.unwrap();ready=true;break}}
 assert!(ready,"original comparator action exceeded its existing bound");let step=*action.as_ref().unwrap().recorded_reply().unwrap().as_ref().expect("original comparator failure stays resident");assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(g));assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),g,heap);
 let mut output=None;let d=OriginalEffectAuthority::<P>::copy_success_demand().unwrap();let g=grant(d);let((poll,marker),heap)=observe(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(authority.copy_success_into(context,action.as_mut().unwrap(),&mut output,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native success handoff stayed pending")};let progress=turn.result.unwrap().unwrap();assert_eq!(marker,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,g,heap);authority.finish(&mut action).unwrap();assert_eq!(output,Some(step));
 let bytes=size_of::<Option<RetainedCloneStep>>();let g=grant(crate::RetirementDemand{copy_bytes:bytes,depth:1,..Default::default()});let((poll,marker),heap)=observe(||bank.run(g,1,|effect|{assert!(effect.performed(1).unwrap());drop(output.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native success header stayed pending")};assert_eq!(marker,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap(),g,heap);step
}
#[derive(Clone,Copy)]
pub(crate) enum Op{Birth,Compare(BoundedOrdGrant,usize),Take,BeginClose,Close(usize),Release}
pub(crate) struct Driver<K>(pub(crate) OriginalSourceTurnIdentity,pub(crate) std::marker::PhantomData<fn()->K>);
pub(crate) struct Context<'a,'b,K:BoundedOrd>{pub(crate) cursor:&'a mut Option<K::Cursor>,pub(crate) left:RetainedCloneRef<'b,K>,pub(crate) right:RetainedCloneRef<'b,K>,pub(crate) order:&'a mut Option<Ordering>,pub(crate) source:OriginalSourceTurnIdentity,pub(crate) op:Op}
impl<K:BoundedOrd> OriginalEffectProducer for Driver<K>{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Context<'a,'b,K>where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Context<'a,'b,K>)->Result<(),ValueError>where 'b:'a{if c.source!=self.0{return Err(ValueError::invariant("comparator fixture changed its original Source"))}Ok(())}
 fn source_turn<'a,'b>(&self,c:&Context<'a,'b,K>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.source)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Context<'a,'b,K>,e:&mut crate::RetainedAllocationEffect<'_>,r:Reply<'r>)->Result<Complete<'r>,ValueError>where 'b:'a{match c.op{Op::Birth=>K::admit_bounded_ord_cursor_into(c.cursor,e,r),Op::Compare(g,b)=>c.cursor.as_mut().unwrap().compare_into(c.left,c.right,g,b,e,r),Op::Take=>c.cursor.as_mut().unwrap().take_ordering_into(c.order,e,r),Op::BeginClose=>c.cursor.as_mut().unwrap().begin_close_into(e,r),Op::Close(b)=>c.cursor.as_mut().unwrap().close_into(b,e,r),Op::Release=>{let witness=c.cursor.as_ref().unwrap().terminal_release().expect("real native comparator lifecycle");let mut native=None;drop(witness.inline_into(c.cursor,e,OriginalEffectReply::borrow(&mut native)?)?);semio_framework_value_retirement::forward_original_value_reply(&mut native,r)}}}
 fn recover<'r,'a,'b>(&mut self,c:&mut Context<'a,'b,K>,e:&mut crate::RetainedAllocationEffect<'_>,r:Reply<'r>)->Result<Complete<'r>,ValueError>where 'b:'a{match c.op{Op::Birth=>K::recover_admit_bounded_ord_cursor_into(c.cursor,e,r),Op::Compare(g,b)=>c.cursor.as_mut().unwrap().recover_compare_into(c.left,c.right,g,b,e,r),Op::Take=>c.cursor.as_mut().unwrap().recover_take_ordering_into(c.order,e,r),Op::BeginClose=>c.cursor.as_mut().unwrap().recover_begin_close_into(e,r),Op::Close(b)=>c.cursor.as_mut().unwrap().recover_close_into(b,e,r),Op::Release=>Err(ValueError::invariant("native lifecycle has no unrecorded callback"))}}
}
pub(crate) fn close_comparator<'a,K:BoundedOrd>(cursor:&mut Option<K::Cursor>,left:RetainedCloneRef<'a,K>,right:RetainedCloneRef<'a,K>,bank:&mut EffectBank,authority:&mut OriginalEffectAuthority<Driver<K>>,body:usize){
 let source=bank.source_witness().identity();let mut order=None;let d=cursor.as_ref().unwrap().begin_close_demand();let mut c=Context{cursor,left,right,order:&mut order,source,op:Op::BeginClose};paid(bank,authority,&mut c,grant(d),1);
 for _ in 0..100000{if cursor.as_ref().unwrap().terminal_is_empty(){break}let d=cursor.as_ref().unwrap().close_demands(body).unwrap();let work=cursor.as_ref().unwrap().close_work_demand(body).unwrap();let mut c=Context{cursor,left,right,order:&mut order,source,op:Op::Close(body)};paid(bank,authority,&mut c,grant(d),work);}assert!(cursor.as_ref().unwrap().terminal_is_empty());let d=cursor.as_ref().unwrap().terminal_release().unwrap().inline_demand();let mut c=Context{cursor,left,right,order:&mut order,source,op:Op::Release};paid(bank,authority,&mut c,grant(d),1);assert!(cursor.is_none())
}
struct RetireDriver<T>(OriginalSourceTurnIdentity,std::marker::PhantomData<fn()->T>);
impl<T:semio_framework_value_retirement::RetireOwned> OriginalEffectProducer for RetireDriver<T>{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(&'a mut semio_framework_value_retirement::retirement::controlled::ControlledRetirement<T>,OriginalSourceTurnIdentity,usize)where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if self.0!=c.1{return Err(ValueError::invariant("retirement fixture changed actual Source"))}Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.1)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut crate::RetainedAllocationEffect<'_>,r:Reply<'r>)->Result<Complete<'r>,ValueError>where 'b:'a{c.0.step_into(c.2,e,r)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut crate::RetainedAllocationEffect<'_>,r:Reply<'r>)->Result<Complete<'r>,ValueError>where 'b:'a{c.0.recover_step_into(c.2,e,r)}
}
pub(crate) fn retire<T:semio_framework_value_retirement::RetireOwned>(value:T,bank:&mut EffectBank){let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::retain(value);let source=bank.source_witness().identity();let mut authority=OriginalEffectAuthority::new(RetireDriver::<T>(source,std::marker::PhantomData));for _ in 0..100000{if owner.terminal_is_empty(){break}let d=owner.selected_demand(4096).unwrap();let work=owner.next_computational_work(4096).unwrap();paid(bank,&mut authority,&mut(&mut owner,source,4096),grant(d),work);}assert!(owner.terminal_is_empty());assert!(authority.into_producer().is_ok());assert_eq!(observe(||drop(owner)).1,(0,0))}
pub(crate) fn refusal<'a,'b,P>(bank:&mut EffectBank,authority:&mut OriginalEffectAuthority<P>,context:&mut P::Context<'a,'b>,g:RetainedCloneGrant,units:u64,expected:&str)where 'b:'a,P:OriginalEffectProducer<Output=RetainedCloneStep,Failure=OriginalRetirementFailure>{
 let(mut action,mut output)=(None,None);let((poll,marker),heap)=observe(||bank.run(g,units,|effect|{let before=effect.performed_boundary();assert!(authority.drive(context,effect,&mut action).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_since(before).unwrap()})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native refusal stayed pending")};turn.result.unwrap();assert_eq!(marker,None);assert_eq!(heap,(0,0));let error=action.as_ref().unwrap().recorded_reply().unwrap().as_ref().unwrap_err();assert!(error.primary().unwrap().message.contains(expected));assert_eq!(bank.take_admitted(),if turn.work==0{None}else{Some(true)});bank.post(error.retained_progress(),g,heap);
 let d=OriginalEffectAuthority::<P>::transfer_reply_demand().unwrap();let g=grant(d);let((poll,marker),heap)=observe(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(authority.transfer_reply_into(context,&mut action,&mut output,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native refusal transfer stayed pending")};assert_eq!(marker,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap().unwrap(),g,heap);let mut error=None;let d=crate::RetirementDemand{copy_bytes:size_of::<Option<Result<RetainedCloneStep,OriginalRetirementFailure>>>()+size_of::<Option<OriginalRetirementFailure>>(),depth:1,..Default::default()};let g=grant(d);let((poll,marker),heap)=observe(||bank.run(g,1,|effect|{assert!(output.as_ref().unwrap().is_err());assert!(effect.performed(1).unwrap());let Some(Err(cause))=output.take()else{unreachable!("validated actual native refusal")};error=Some(cause);RetainedWorkPoll::Complete(RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native refusal variant handoff stayed pending")};assert_eq!(marker,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap(),g,heap);retire(error.take().unwrap(),bank)
}
